<template><div class="page"><Header/><main class="panel"><h1>Payment status</h1><p v-if="state==='loading'">Checking payment…</p><p v-else-if="state==='error'" class="error">{{error}} <button @click="start">Retry status check</button></p><template v-else-if="attempt"><p class="status" :class="statusClass">{{statusText}}</p><p v-if="attempt.amount!==undefined">Payment amount: <strong>{{money(attempt.amount,attempt.currency)}}</strong></p><p v-if="attempt.orderId">Order: <router-link :to="'/profile/orders/'+attempt.orderId">{{attempt.orderId}}</router-link></p><p v-if="order">Order status: {{order.status||'Unknown'}} · {{money(order.amount,order.currency)}}</p><p v-if="state==='unknown'" class="muted">The backend returned an unrecognized status. No success or failure is inferred.</p><p v-if="state==='processing'" class="muted">{{ pollingExhausted ? 'Payment status has not been confirmed. Please retry later.' : 'Status will be checked at a limited interval.' }} <button v-if="pollingExhausted" @click="start">Retry status check</button></p><p v-if="orderSyncError" class="muted">Payment is confirmed, but the order could not be refreshed. Please check it again later.</p></template><div class="actions"><router-link v-if="attempt?.orderId" :to="'/profile/orders/'+attempt.orderId">View order</router-link><router-link to="/profile/orders">My orders</router-link><router-link to="/">Continue shopping</router-link></div></main><Footer/></div></template>
<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';import {useRoute} from 'vue-router';import Header from '@/components/Header.vue';import Footer from '@/components/Footer.vue';import {getPaymentAttempt,normalizePaymentStatus,type PaymentAttempt,PaymentApiError} from '@/api/payments';import {getOrderDetail,type OrderRecord} from '@/api/orders';import {getCustomerAuthState} from '@/utils/customerAuth'
const route=useRoute(),attempt=ref<PaymentAttempt|null>(null),order=ref<OrderRecord|null>(null),state=ref<'loading'|'success'|'failed'|'cancelled'|'processing'|'unknown'|'error'>('loading'),error=ref(''),timer=ref<ReturnType<typeof setTimeout>|null>(null),polls=ref(0),stopped=ref(false),pollingExhausted=ref(false),orderSyncError=ref(false);let sequence=0
const statusText=computed(()=>({success:'Payment confirmed by the server',failed:'Payment failed',cancelled:'Payment cancelled',processing:'Payment is processing',unknown:'Payment status unknown'}[state.value]||'Checking payment status…'));const statusClass=computed(()=>state.value)

function money(value:any,currency='USD'){if(value===undefined||value===null||value==='')return'—';const n=Number(value);return Number.isFinite(n)?new Intl.NumberFormat(undefined,{style:'currency',currency:currency||'USD'}).format(n):String(value)}
function stopPolling(){if(timer.value)clearTimeout(timer.value);timer.value=null}
async function check(){stopPolling();const id=String(route.query.attemptId||'');const current=++sequence;if(!getCustomerAuthState().isAuthenticated){state.value='error';error.value='Please sign in with a customer account to view payment status.';return}if(!id){state.value='error';error.value='No payment attempt ID was supplied. Payment result cannot be inferred from this page URL.';return}state.value='loading';try{const result=await getPaymentAttempt(id);if(stopped.value||current!==sequence)return;attempt.value=result;order.value=null;orderSyncError.value=false;state.value=normalizePaymentStatus(result.status);if(state.value==='success'&&result.orderId){try{const resultOrder=await getOrderDetail(result.orderId);if(stopped.value||current!==sequence)return;order.value=resultOrder}catch{if(stopped.value||current!==sequence)return;orderSyncError.value=true}}if(state.value==='processing'&&polls.value<10&&!stopped.value){polls.value++;timer.value=setTimeout(()=>void check(),5000)}else if(state.value==='processing'){pollingExhausted.value=true}}catch(e){if(stopped.value||current!==sequence)return;state.value='error';error.value=e instanceof PaymentApiError&&e.status===401?'Your session expired. Please sign in again.':e instanceof Error?e.message:'Unable to query payment status.'}}
function start(){stopPolling();sequence++;stopped.value=false;polls.value=0;pollingExhausted.value=false;attempt.value=null;order.value=null;void check()}watch(()=>route.query.attemptId,start,{immediate:true});onBeforeUnmount(()=>{stopped.value=true;sequence++;stopPolling()})
</script>
<style scoped>.page{min-height:100vh;background:#f4f4f5;color:#333;font:13px Arial}.panel{max-width:700px;margin:36px auto;background:#fff;border:1px solid #e3e6e9;border-radius:6px;padding:22px}.panel h1{font-size:18px}.status{font-size:16px;font-weight:600}.success{color:#18794e}.failed,.cancelled,.error{color:#a63805}.processing{color:#8a5b00}.unknown,.muted{color:#656d76}.actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:20px}.actions a{font-size:13px;color:#0878b0}@media(max-width:700px){.panel{margin:14px 12px;padding:16px}}</style>

